import{_ as t,o as a,c as i,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy verification and evaluation protocol","description":"This protocol separates technical verification, learner evaluation and school assessment. It is a proposed protocol for review, not ethics approval, a validated instrument or ","frontmatter":{"title":"Chainy verification and evaluation protocol","description":"This protocol separates technical verification, learner evaluation and school assessment. It is a proposed protocol for review, not ethics approval, a validated instrument or ","source":"docs/qa-evaluation.md","category":"Research & evaluation","sourceUpdated":null,"outline":[2,3]},"headers":[],"relativePath":"content/docs/qa-evaluation.md","filePath":"content/docs/qa-evaluation.md"}'),s={name:"content/docs/qa-evaluation.md"};function n(o,e,d,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-verification-and-evaluation-protocol">Chainy verification and evaluation protocol<a class="header-anchor" href="#chainy-verification-and-evaluation-protocol" aria-label="Link to this section">​</a></h1><p>This protocol separates technical verification, learner evaluation and school assessment. It is a proposed protocol for review, not ethics approval, a validated instrument or a report of completed sessions. English is the confirmed first language. Sean owns the research protocol; Christian owns technical checks; Sherwin coordinates the site; Miguel records usability issues; Luis reviews visual comprehension.</p><h2 id="readiness-and-evidence">Readiness and evidence<a class="header-anchor" href="#readiness-and-evidence" aria-label="Link to this section">​</a></h2><p>Begin internal tests with synthetic codes/records. Real learner sessions require the school&#39;s research process, site arrangements, applicable participant/guardian permissions, instrument review and an approved custodian/retention plan. The target learners are 12–17, especially low-income and remote communities with limited technology access; do not invent sample counts, consent, bookings or approval. Assess instruction readability and initial touch-control understanding without assuming previous smartphone use or personal device ownership.</p><p>Pre-final needs complete chapters, functional core modules and pilot-area evidence. The supplied rating scale does not specify actual criterion meanings or a completion calculation. The precise ISO instrument/version remains pending; ISO 2010 is retained as unresolved source wording, not a chosen standard.</p><p>Record build commit/version, content/instrument versions, device, OS/API, tester, date, setup, steps, expected/actual result and evidence link for every test. Actual outcomes start Not run. A staff report of a future session is not a test result.</p><h2 id="technical-acceptance-matrix">Technical acceptance matrix<a class="header-anchor" href="#technical-acceptance-matrix" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Test</th><th>Requirement</th><th>Steps and expected result</th></tr></thead><tbody><tr><td>T01</td><td>CH-R01</td><td>Fresh install, airplane mode, start/resume and finish a mission; all required content is local</td></tr><tr><td>T02</td><td>CH-R02</td><td>Order/link supplied records using bounded controls; incorrect order/link gives actionable feedback; correction succeeds. Free placement and multiple spatial layouts are superseded acceptance criteria</td></tr><tr><td>T03</td><td>CH-R03</td><td>Submit correct and incorrect record orders; outcomes follow documented rules rather than screen position</td></tr><tr><td>T04</td><td>CH-R04</td><td>Alter data and break a link; detect discrepancy against reference; recomputed local hashes do not erase the reference comparison</td></tr><tr><td>T05</td><td>CH-R05</td><td>Three replicas agree, one diverges, all diverge; repair follows the toy rule or reports no agreement</td></tr><tr><td>T06</td><td>CH-R06</td><td>Train with two example sets and test held-out objects; one prediction changes; missing-class/tie states are handled</td></tr><tr><td>T07</td><td>CH-R07</td><td>Configure a successful and failing route; step trace matches the visible policy; loops terminate at the cap</td></tr><tr><td>T08</td><td>CH-R08</td><td>Complete/replay lessons across Web3, Blockchain and AI; retain first attempt, retries, progress and badges correctly</td></tr><tr><td>T09</td><td>CH-R09</td><td>Use codes A/B on one device; records never mix; restart resumes only the selected profile</td></tr><tr><td>T10</td><td>CH-R09</td><td>Enter an existing code on a second device; evidence can later be grouped by code, but no automatic save restoration is claimed</td></tr><tr><td>T11</td><td>CH-R09</td><td>Interrupt before/during/after commit; recover a consistent checkpoint with no fabricated completion</td></tr><tr><td>T12</td><td>CH-R10</td><td>Export offline, cancel picker, deny/write-fail, retry; no local evidence is deleted</td></tr><tr><td>T13</td><td>CH-R10</td><td>Import same package twice; unique totals unchanged; same ID with conflicting content is quarantined</td></tr><tr><td>T14</td><td>CH-R10</td><td>Reject malformed package, unknown schema and impossible references with clear feedback</td></tr><tr><td>T15</td><td>CH-R11</td><td>Install signed update with migration; existing records remain; simulated migration failure preserves recovery data</td></tr><tr><td>T16</td><td>CH-R01</td><td>Run capped worst-case activity; collect sustained FPS, p95 frame time, PSS, load times and thermal observations</td></tr><tr><td>T17</td><td>CH-R08</td><td>Review onboarding with a first-time user, small-screen text, non-color cues, audio-off operation and tap alternatives to dragging; required instructions stay accessible without internet</td></tr><tr><td>T18</td><td>CH-R12</td><td>Rehearse complete offline defense including relaunch/export and explain known limitations with real evidence</td></tr></tbody></table><p>T01/T09/T12 begin during the first device spike. T02–T08 run while each mechanic is built. The revised local integrated readiness window is October 31–November 2 (previously November 7); testing begins during implementation. No critical data-loss or core-blocking defect may be hidden behind an average score.</p><p>Severity: critical = data loss, failure to start or required activity cannot complete; major = wrong learning feedback/results or unreliable operation; minor = non-blocking presentation. Christian triages technical defects, Sean incorrect assessment/evidence, Sherwin scope tradeoffs. Repeat only affected tests plus smoke checks after a fix.</p><h2 id="learner-session-procedure">Learner session procedure<a class="header-anchor" href="#learner-session-procedure" aria-label="Link to this section">​</a></h2><ol><li>Verify approved participant/site arrangements and use the frozen study build. Record study/site code and device/build details without unnecessary identity.</li><li>Teacher issues/confirms the learner code and explains its purpose. Participation/withdrawal follows the approved protocol. Research results are not public game rankings.</li><li>Collect the approved pre-assessment before teaching or showing answers.</li><li>Provide a consistent short control tutorial. Learner completes missions with a consistent hint policy; record interruptions and assistance.</li><li>Collect the approved post-assessment and usability feedback. Game quiz retries are separate from research pre/post scores.</li><li>Teacher supervises evidence export and verifies receipt. Flag missing or mismatched codes for review rather than guessing.</li><li>End the profile session and prepare the device for the next learner. Retain evidence according to the approved policy.</li></ol><p>Proposed overall session is 45–60 minutes including assessment and breaks; test the timing internally before booking. Do not crowd learners to fit the calendar. A pilot on a reduced approved feature set must be disclosed as such; it cannot validate unseen modules.</p><h2 id="draft-assessment-blueprint">Draft assessment blueprint<a class="header-anchor" href="#draft-assessment-blueprint" aria-label="Link to this section">​</a></h2><p>Proposed nine scored items: three per world. Sean drafts parallel pre/post forms with equivalent difficulty and educator review; the following are item intents, not validated questions. The <a href="/Chainy-Docs/content/docs/learning-foundations.html">beginner materials</a> supply formative practice and keys; do not simply reuse practiced answers as a claim of independent learning transfer.</p><table><thead><tr><th>Group</th><th>Three item intents</th></tr></thead><tbody><tr><td>Web3</td><td>Explain shared versus single-operator control without claiming automatic fairness; protect private information; recognize a suspicious request and choose a safe response</td></tr><tr><td>Blockchain</td><td>Apply record order/link rules; detect a change against a reference; interpret disagreement under the stated three-copy rule</td></tr><tr><td>AI/agent</td><td>Predict effects of example quality; interpret held-out errors; distinguish a classifier prediction from a policy-controlled action</td></tr></tbody></table><p>Use an explicit answer key and score each item 0/1 unless the adviser approves a reasoning rubric. Version prompts/keys; document reviewer changes. Do not claim psychometric validity or reliability without its actual supporting procedure and results.</p><p>Draft usability prompts for adviser review: instructions were understandable; controls were easy to use; feedback helped explain errors; activities helped me understand the concepts. Use a consistent response scale, avoid leading interviewer explanations, and invite a short optional verbal comment recorded without personal details only if approved. This is not an ISO-compliant questionnaire by declaration.</p><h2 id="analysis-and-manuscript-use">Analysis and manuscript use<a class="header-anchor" href="#analysis-and-manuscript-use" aria-label="Link to this section">​</a></h2><p>Define the unit of analysis as learner, session or device before collecting data. Use learner codes to pair the same learner across pre/post. Report recruited/completed/paired counts, missing data, item-level counts, total-score summaries and observed paired differences. Keep incomplete/duplicate sessions visible in a disposition log. Do not silently pair different participants using a shared device label.</p><p>Sean selects any inferential method with the adviser based on sample/design/distribution assumptions. A one-group pre/post result is evidence of observed change, not proof that the game alone caused it. Report usability separately from concept scores and disclose practice effects, supervision, convenience sampling, limited devices and other actual limitations.</p><p>Chapter IV uses actual preliminary and system evaluation evidence. Chapter V answers the stated objectives only to the extent supported. The school instrument and final sample size remain open; no statistical findings are supplied by this design document.</p><h2 id="release-and-handover-checklist">Release and handover checklist<a class="header-anchor" href="#release-and-handover-checklist" aria-label="Link to this section">​</a></h2><p>Freeze app/content/instrument versions for the demonstration, preserve signed APK and source commit, test install/update/offline launch/save/relaunch/export, inventory asset licenses and guides, and record known limitations. Confirm signing/data custodians, backup device or recovery plan, and secure handover. Manuals and evidence index must match the actual build rather than planned screenshots.</p><h2 id="october-8-proposed-school-beta-and-readiness-gate">October 8 proposed school beta and readiness gate<a class="header-anchor" href="#october-8-proposed-school-beta-and-readiness-gate" aria-label="Link to this section">​</a></h2><p>The user identified <strong>November 3–6, 2026 at Tambunan National High School, Marinduque</strong> as a possible beta window. Treat this as tentative until CH-24 records the booking, school contact, participant count/age range, usable devices, session times, travel/logistics and required permissions. Sean must confirm which preliminary and system evaluation evidence this session can legitimately supply; a beta is not automatically the complete required study. Do not assume a second visit November 8–13.</p><p>The revised local forecast requires CH-13 integrated candidate by October 30 and CH-14 device/records/update readiness October 31–November 2, after their original prerequisite gates. Christian records technical readiness; Sean records protocol/instrument readiness; Sherwin records site/permission readiness; Miguel supplies actual test evidence and Luis checks visual comprehension. Learner sessions require all three readiness dispositions. Missing core functionality, data-loss defects, unapproved instruments or unconfirmed site access block the proposed session.</p><p>Retain the user&#39;s phone specification: Android 10+/11+, 4 GB RAM, 64 GB total storage, ARM64, ES 3.2 or Vulkan 1.1, entry-to-mid-range GPU. This describes a proposed device class, not a measured minimum or app size. Existing Android 11+ recommendation and Android 10 test candidate remain provisional; actual phone models and usable storage must be recorded. Test offline behavior on the actual participating devices before the beta.</p><p>Preserve the supplied rubric: four categories, two criteria each, eight criteria at 1–4 points each, 32 total; 4 = exemplary (90–100%), 3 = proficient (80–89%), 2 = developing (70–79%), 1 = needs improvement (below 70%). These are quality-rating bands. Criterion names and a 60-percent-completion formula remain unknown; no task percentage, test pass rate or questionnaire mean substitutes for them. Exact ISO instrument/version remains unresolved.</p><p>Reserve November 7–13 for actual export validation, missing/duplicate record disposition, analysis and prioritized fixes/regression. Final manuscript target is November 16; offline rehearsals November 17–20; confirmed pre-final November 21. If the candidate/readiness gate fails, Sherwin/Sean must resolve the school/adviser consequences and record the evidence gap. Internal synthetic tests remain technical evidence only. Preserve local SQLite records on export failures; teacher transfer and receipt are explicit operations outside offline gameplay.</p></div>',1)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
